const fs = require('fs');
const executeTreasuryAction = require('./treasury');

async function runTests() {
    const results = [];

    const actions = [
        { type: 'create_wallet', userId: 'user_001', chain: 'polygon-amoy' },
        { type: 'check_balance', walletAddress: '0x1234567890123456789012345678901234567890', chain: 'polygon-amoy' },
        { type: 'mint_receipt', email: 'test@example.com', purchaseId: 'purch_999' },
        { type: 'unknown_action' }
    ];

    for (const action of actions) {
        try {
            const result = await executeTreasuryAction(action);
            results.push({ action_type: action.type, result });
        } catch (e) {
            results.push({ action_type: action.type, result: { success: false, error: e.message } });
        }
    }

    fs.writeFileSync('/home/user/treasury_test_results.json', JSON.stringify(results, null, 2));
    process.exit(0);
}

runTests();

